head.script:
// 행 짝/홀에 따라 다른 itemSet 의 select 로 지정
scwin.getType = function(info) {
	var dataSetNm = (info.rowIndex % 2 == 0) ? "DS_LNUP_ITM484" : "DS_LNUP_ITM537";
	return {
		id: "dynamic_select_" + info.rowIndex + "_" + info.colIndex,
		inputType: "select",
		options: { viewType: "icon" },
		itemSet: { nodeset: "data:" + dataSetNm, label: "lnup_dtl_itm_nm", value: "lnup_dtl_itm_cd" }
	};
};

scwin.onpageload = function() {
	DS_ztpm_lnup_itm_2000.setJSON([
		{ "lnup_itm_cd": "537", "lnup_itm_nm": "LTE 지원 Band", "chk_col": "1", "lnup_dtl_itm_cd_2000": "01" },
		{ "lnup_itm_cd": "484", "lnup_itm_nm": "SMS호환성탑재버젼", "chk_col": "1", "lnup_dtl_itm_cd_2000": "01" }
	]);
	DS_LNUP_ITM484.setJSON([
		{ "lnup_dtl_itm_cd": "01", "lnup_dtl_itm_nm": "없음" },
		{ "lnup_dtl_itm_cd": "02", "lnup_dtl_itm_nm": "USIM 잠금해제 규격(국내향)" },
		{ "lnup_dtl_itm_cd": "03", "lnup_dtl_itm_nm": "USIM 잠금해제 규격(해외향)" }
	]);
	DS_LNUP_ITM537.setJSON([
		{ "lnup_dtl_itm_cd": "01", "lnup_dtl_itm_nm": "없음" },
		{ "lnup_dtl_itm_cd": "02", "lnup_dtl_itm_nm": "B5(850MHz)" },
		{ "lnup_dtl_itm_cd": "03", "lnup_dtl_itm_nm": "B5 B3(850MHz1.8GHz)" },
		{ "lnup_dtl_itm_cd": "04", "lnup_dtl_itm_nm": "B3(1.8GHz KT)" },
		{ "lnup_dtl_itm_cd": "05", "lnup_dtl_itm_nm": "B5 B3 B1 B7(850MHz 1.8GHz 2.1GHz 2.6GHz)" },
		{ "lnup_dtl_itm_cd": "06", "lnup_dtl_itm_nm": "B1, B2, B3, B5, B7, B8(2.1GHz,1.9GHz, 1.8GHz, 850MHz, 2.6GHz, 900MHz)" },
		{ "lnup_dtl_itm_cd": "07", "lnup_dtl_itm_nm": "B5, B3, B1(850MHz, 1.8Hz, 2.1GHz)" },
		{ "lnup_dtl_itm_cd": "08", "lnup_dtl_itm_nm": "B1, B3, B5, B7, B8(2.1GHz,1.8GHz, 850MHz, 2.6GHz, 900MHz)" },
		{ "lnup_dtl_itm_cd": "09", "lnup_dtl_itm_nm": "B1, B5(2.1GHz, 850GHz)" }
	]);
};
